        if (this.health <= 0) {
          this.destroy();
        }
      }
      this.speed = -this.speed * 0.35; // bounce back
      if (col.pushX) this.x += col.pushX;
      if (col.pushY) this.y += col.pushY;
    }
  }

  addSkidMark() {
    this.skidMarks.push({
      x: this.x,
      y: this.y,
      angle: this.angle,
      life: 200,
    });
    if (this.skidMarks.length > 50) this.skidMarks.shift();
